package routes

import (
	"encoding/base64"
	"html/template"
	"net/http"

	"github.com/gin-gonic/gin"
)

func loadFallbackTemplates() *template.Template {
	tmpl := template.New("")
	template.Must(tmpl.New("login.html").Parse(fallbackLoginHTML))
	template.Must(tmpl.New("explore.html").Parse(fallbackExploreHTML))
	template.Must(tmpl.New("order.html").Parse(fallbackOrderHTML))
	return tmpl
}

func serveFallbackStatic(c *gin.Context) {
	switch c.Param("filepath") {
	case "/css/style.css":
		c.Data(http.StatusOK, "text/css; charset=utf-8", []byte(fallbackStyleCSS))
	case "/js/app.js":
		c.Data(http.StatusOK, "application/javascript; charset=utf-8", []byte(fallbackAppJS))
	case "/img/avatar.png":
		data, _ := base64.StdEncoding.DecodeString(fallbackAvatarB64)
		c.Data(http.StatusOK, "image/png", data)
	case "/img/saas-preview.png":
		data, _ := base64.StdEncoding.DecodeString(fallbackPreviewB64)
		c.Data(http.StatusOK, "image/png", data)
	default:
		c.Status(http.StatusNotFound)
	}
}

